/* From Uiverse.io by ahmed150up - Tags: radio */
.__UIV_SCOPE__ .radio-group {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .radio-button {
  display: flex;
  align-items: center;
  margin-bottom: 15px;
  cursor: pointer;
}

.__UIV_SCOPE__ .radio-icon {
  width: 20px;
  height: 20px;
  margin-right: 10px;
  fill: #fff;
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .radio-button:hover .radio-icon {
  transform: scale(1.2);
  fill: #2ed573;
}

.__UIV_SCOPE__ .radio-button input[type="radio"] {
  opacity: 0;
  position: absolute;
}

.__UIV_SCOPE__ .radio-text {
  font-size: 18px;
  color: #fff;
  font-weight: bold;
}

.__UIV_SCOPE__ .radio-button::before {
  content: "";
  display: inline-block;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid #fff;
  margin-right: 10px;
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .radio-button:hover .radio-text {
  font-size: 18px;
  color: #2ed573;
  font-weight: bold;
}

.__UIV_SCOPE__ .radio-button:hover::before {
  border: 2px solid #2ed573;
}

.__UIV_SCOPE__ .radio-button input[type="radio"]:checked + .radio-icon {
  fill: #2ed573;
}

.__UIV_SCOPE__ .radio-button input[type="radio"]:checked + .radio-icon circle:last-child {
  opacity: 1;
}
